def normalize_sport_name(sport: str) -> str:
    """Return the canonical sport name when possible."""
    if not sport:
        return ""
    compact = " ".join(str(sport).strip().lower().split())
    aliases = {
        "football": "Soccer",
        "soccer": "Soccer",
        "futebol": "Soccer",
        "waterpolo": "Water Polo",
        "water polo": "Water Polo",
        "polo aquatico": "Water Polo",
        "polo aquático": "Water Polo",
        "tabletennis": "Table Tennis",
        "ping pong": "Table Tennis",
        "ping-pong": "Table Tennis",
        "track": "Running",
        "athletics": "Running",
        "track and field": "Running",
        "martial arts": "Martial Arts",
        "combat sports": "Martial Arts",
    }
    if compact in aliases:
        return aliases[compact]
    for name in TRAINING_CATALOG:
        if compact == name.lower():
            return name
    for name in TRAINING_CATALOG:
        if compact.replace(" ", "") == name.lower().replace(" ", ""):
            return name
    return str(sport).strip()


def get_supported_sports() -> List[str]:
    return list(TRAINING_CATALOG.keys())


def get_sport_metadata(sport: str) -> Dict[str, str]:
    sport_name = normalize_sport_name(sport)
    return dict(SPORT_METADATA.get(sport_name, {}))


def get_all_sessions(sport: str) -> List[Dict[str, Any]]:
    sport_name = normalize_sport_name(sport)
    return list(TRAINING_CATALOG.get(sport_name, []))


def get_sessions(
    sport: str,
    level: Optional[str] = None,
    training_alone: Optional[bool] = None,
    partners_count: Optional[int] = None,
    duration_min: Optional[int] = None,
    limit: Optional[int] = None,
) -> List[Dict[str, Any]]:
    """
    Filter the embedded catalog.

    level may be: Never Played Before, Beginner, Intermediate, Advanced, Elite.
    training_alone=True returns solo/both sessions.
    training_alone=False returns group/both sessions.
    partners_count is kept for app compatibility; if partners_count > 0, it behaves like training_alone=False.
    """
    sessions = get_all_sessions(sport)

    if level:
        wanted = " ".join(str(level).strip().lower().split())
        if wanted in {"learn", "learn how to play", "never played", "never played before", "new"}:
            wanted = "never played before"
        sessions = [s for s in sessions if str(s.get("level", "")).lower() == wanted]

    if partners_count is not None and partners_count > 0:
        training_alone = False

    if training_alone is True:
        sessions = [s for s in sessions if bool(s.get("solo_allowed"))]
    elif training_alone is False:
        sessions = [s for s in sessions if bool(s.get("group_allowed"))]

    if duration_min is not None and sessions:
        # Prefer sessions near the requested duration, but keep all returned sorted by closeness.
        sessions = sorted(sessions, key=lambda s: abs(int(s.get("duration_min") or duration_min) - int(duration_min)))

    if limit is not None:
        return sessions[: int(limit)]
    return sessions


def get_learn_sessions(sport: str) -> List[Dict[str, Any]]:
    return get_sessions(sport, level="Never Played Before")


def get_level_sessions(sport: str, level: str, training_alone: Optional[bool] = None) -> List[Dict[str, Any]]:
    return get_sessions(sport, level=level, training_alone=training_alone)


def choose_session(
    sport: str,
    level: str,
    training_alone: Optional[bool] = None,
    partners_count: Optional[int] = None,
    duration_min: Optional[int] = None,
    seed: Optional[int] = None,
) -> Optional[Dict[str, Any]]:
    options = get_sessions(
        sport=sport,
        level=level,
        training_alone=training_alone,
        partners_count=partners_count,
        duration_min=duration_min,
    )
    if not options:
        return None
    rng = random.Random(seed) if seed is not None else random
    # If duration was supplied, get_sessions sorted by closeness, so pick among top 3 for variety.
    pool = options[:3] if duration_min is not None else options
    return dict(rng.choice(pool))


def validate_catalog() -> Dict[str, Any]:
    counts = {sport: len(sessions) for sport, sessions in TRAINING_CATALOG.items()}
    total = sum(counts.values())
    missing_blocks = [
        s.get("id")
        for sessions in TRAINING_CATALOG.values()
        for s in sessions
        if not s.get("training_blocks")
    ]
    return {
        "sports": len(TRAINING_CATALOG),
        "total_sessions": total,
        "counts_by_sport": counts,
        "valid": len(TRAINING_CATALOG) == 18 and total == 774 and all(v == 43 for v in counts.values()) and not missing_blocks,
        "missing_training_blocks": missing_blocks,
    }


if __name__ == "__main__":
    print(validate_catalog())
